{"files":{"engine.mjs":"// engine.mjs - Pure-function contract for Peg Bloom

/**
 * Returns all legal move triples [from, over, to] for the current peg configuration.
 * @param {object} puzzle - Puzzle object with cells, directions.
 * @param {string[]} pegs - Array of occupied cell strings "x,y".
 * @returns {Array<[string, string, string]>} Array of legal moves.
 */
export function legalMoves(puzzle, pegs) {
  const pegSet = new Set(pegs);
  const moves = [];
  for (const from of pegs) {
    const [fx, fy] = from.split(',').map(Number);
    for (const [dx, dy] of puzzle.directions) {
      const ox = fx + dx, oy = fy + dy;
      const tx = fx + 2 * dx, ty = fy + 2 * dy;
      const over = `${ox},${oy}`;
      const to = `${tx},${ty}`;
      if (pegSet.has(from) && pegSet.has(over) && !pegSet.has(to) &&
          puzzle.cells.includes(over) && puzzle.cells.includes(to)) {
        moves.push([from, over, to]);
      }
    }
  }
  return moves;
}

/**
 * Applies a move, returning a new peg array. Throws if illegal.
 * @param {object} puzzle - Puzzle object.
 * @param {string[]} pegs - Current occupied cells.
 * @param {[string, string, string]} move - [from, over, to].
 * @returns {string[]} New peg array.
 */
export function applyMove(puzzle, pegs, move) {
  const [from, over, to] = move;
  const pegSet = new Set(pegs);
  if (!pegSet.has(from) || !pegSet.has(over) || pegSet.has(to)) {
    throw new Error(`Illegal move: ${move.join(' -> ')}`);
  }
  const newPegs = pegs.filter(p => p !== from && p !== over).concat(to);
  return newPegs;
}

/**
 * Checks if the current peg set exactly matches the goal.
 * @param {object} puzzle - Puzzle object with goal array.
 * @param {string[]} pegs - Current occupied cells.
 * @returns {boolean}
 */
export function isSolved(puzzle, pegs) {
  const goalSet = new Set(puzzle.goal);
  const pegSet = new Set(pegs);
  if (goalSet.size !== pegSet.size) return false;
  for (const cell of goalSet) {
    if (!pegSet.has(cell)) return false;
  }
  return true;
